pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 bonusAmount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(bonusAmount > 0);
        // The reference getFirstWithdrawalBonus gives a fixed 100 wei bonus
        // We use the public getter rewardsForA via parameterization in the assertion.
        // Deploy a helper that can receive ETH without reverting.
        Helper helper = new Helper();
        address target = address(helper);
        vm.deal(target, 0);
        vm.prank(target);
        c.getFirstWithdrawalBonus(target);
        // Now rewardsForA[target] was set to 100 and withdrawReward was called.
        // The property: after withdrawReward completes, the mapping must be zero.
        // We read the public getter rewardsForA(address) from C.
        uint rewardAfter = c.rewardsForA(target);
        assertTrue(rewardAfter == 0);
    }
}

contract Helper {
    fallback() external payable { }
}

