pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 bonusCount) public {
        // Keep recipient nonzero and not the contract itself
        vm.assume(recipient != address(0) && recipient != address(c));
        // bound bonusCount to a reasonable range (1-5) so fuzzer explores multiple bonus claims
        bonusCount = bound(bonusCount, 1, 5);

        // Deploy a reentrant attacker that calls getFirstWithdrawalBonus repeatedly in its receive
        Attacker attacker = new Attacker(address(c), bonusCount);
        vm.deal(address(attacker), 0); // not needed but explicit
        vm.deal(address(c), 1000 ether); // seed contract with enough ether

        // Record balance before attack
        uint256 balanceBefore = address(c).balance;
        // Drive the attack; attacker will call getFirstWithdrawalBonus multiple times via reentrancy
        attacker.attack();
        uint256 balanceAfter = address(c).balance;

        // The invariant: contract balance should never decrease by more than bonuses properly claimed.
        // In reference, reentrancy is blocked by _nonReentrant, so balance diff equals claimedBonus * 100.
        // In bug, zeroing happens after call, so reentrancy can double-spend, making balance drop more.
        assertTrue(balanceBefore - balanceAfter <= bonusCount * 100);
    }
}

contract Attacker {
    C public target;
    uint256 public callsRemaining;

    constructor(address _target, uint256 _count) {
        target = C(_target);
        callsRemaining = _count;
    }

    function attack() external {
        // initiate first call
        target.getFirstWithdrawalBonus(address(this));
    }

    receive() external payable {
        if (callsRemaining > 0) {
            callsRemaining--;
            // re-enter into getFirstWithdrawalBonus again
            target.getFirstWithdrawalBonus(address(this));
        }
    }
}

