pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        // Deploy a helper that reverts on receive to cause withdrawReward to revert
        Reverter reverter = new Reverter();
        // Use the reverter as the recipient so the external call fails
        // Drive through getFirstWithdrawalBonus which sets rewardsForA and calls withdrawReward
        vm.prank(address(this));
        try c.getFirstWithdrawalBonus(address(reverter)) {} catch {}
        // After the failed withdrawal, rewardsForA should still be zero in the correct contract
        // In the buggy version, zeroing is after the call, so rewardsForA[reverter] > 0
        // The reference zeroes before the call, so it's 0 even on revert (or 0 after success)
        bool result = c.rewardsForA(address(reverter)) == 0; // public getter exists for mapping
        assertTrue(result);
    }
}
contract Reverter {
    fallback() external payable {
        revert("Reverter: forced revert");
    }
}
